import * as fs from "fs-extra";
import jss from "jss";
import preset from "jss-preset-default";
import * as postcss from "postcss";
import * as autoprefixer from "autoprefixer";

import * as elements from "../src/elements";
import { createTheme } from "../src/theming";
import { generateStylesheet } from "../src/css-from-js";

jss.setup({
  ...preset()
});

const mapColorsToCssProperties = (colors: any): [any, any[]] => {
  const { type, ...colorsCopy } = colors;
  const values: any[] = [];
  const extractCssProperties = (obj: any, path = "-", ret = {}) => {
    for (const p in obj) {
      const v = obj[p];
      const property = `${path}-${p}`;
      if (typeof v !== "object") {
        values.push({ property, value: v });
        ret[p] = `var(${property})`;
      } else {
        ret[p] = extractCssProperties(v, property);
      }
    }
    return ret;
  };
  const varColors = extractCssProperties(colorsCopy);
  return [{ type, ...varColors }, values];
};

const stringifyCssProperties = (props: any[]) =>
  "{\n" + props.map(p => `  ${p.property}: ${p.value};`).join("\n") + "\n}\n";

const BRANDS = ["airbus", "skywise"];

BRANDS.forEach(brand => {
  const origTheme = createTheme(brand);
  const {
    color: { modes, ...normal },
    ...rest
  } = origTheme;

  const [colorProperties, normalValues] = mapColorsToCssProperties(normal);

  const theme = {
    color: colorProperties,
    ...rest
  };
  const modalValues = Object.keys(modes).map(mode => {
    const { common, ...modeColors } = modes[mode];
    return mapColorsToCssProperties(modeColors)[1];
  });

  const stylesheet =
    ":root " +
    stringifyCssProperties(normalValues) +
    Object.keys(modes)
      .map(
        (mode, idx) =>
          `[data-theme='${mode}'] ` + stringifyCssProperties(modalValues[idx])
      )
      .join("\n\n") +
    Object.keys(elements)
      .map(name => generateStylesheet(name, elements[name], theme, jss))
      .join("\n\n");

  postcss([autoprefixer])
    .process(stylesheet, { from: undefined })
    .then((result: any) => {
      fs.outputFile(
        `dist/css/${brand}/stylesheet.variabilized.css`,
        result.css,
        err => {
          if (err) {
            console.error(`Couldn't write file`, err);
            throw err;
          }
          console.log(`Generated ${brand} stylesheet`);
        }
      );
    });
});
